```suggestion
				[b]Example:[/b] Possible return value. This means columns [code]0[/code] to [code]4[/code] should be red, and columns [code]5[/code] to the end of the line should be green, Here is a simple example:
				[codeblocks]
				[gdscript]
				# {
				#    0: {
				#	    "color": Color(1, 0, 0)
				#    },
				#    5: {
				#	    "color": Color(0, 1, 0)
				#    }
				# }
				func _get_line_syntax_highlighting(line: int) -&gt; Dictionary:
					var pattern_text = "Godot"
					var result = Dictionary()
					var text_edit = get_text_edit()
					var line_text = text_edit.get_line(line)

					for i in line_text.length():
						var pos = textEdit.search(pattern_text, TextEdit.SearchFlags.SEARCH_MATCH_CASE, line, i)
						if pos.x == -1 or pos.y == -1 or result.has(pos.x):
							continue

						result[pos.x] = { "color": Color(0.0, 0.0, 1.0) }

					for pos in result:
						var pattern_end_index = pos + pattern_text.length()
						if pattern_end_index in result:
							continue

						result[pattern_end_index] = { "color": Color(1.0, 1.0, 1.0) }

					if 0 not in result:
						result[0] = { "color": Color(1.0, 1.0, 1.0) }

					var need_sort_keys = result.keys()

					need_sort_keys.sort()

					var sort_result = Dictionary();
					for sort_key in need_sort_keys:
						sort_result[sort_key] = result[sort_key];

					return sort_result
				[/gdscript]
				[csharp]
				// {
				//   0: {
				//	    "color": Color(1, 0, 0)
				//   },
				//   5: {
				//	    "color": Color(0, 1, 0)
				//   }
				// }
				public override Dictionary _GetLineSyntaxHighlighting(int line)
				{
					string patternText = "Godot";
					Dictionary result = new Dictionary();
					TextEdit textEdit = GetTextEdit();
					string lineText = textEdit.GetLine(line);

					for (var i = 0; i &lt; lineText.Length; i++)
					{
						Vector2I pos = textEdit.Search(patternText, (uint)SearchFlags.MatchCase, line, i);

						if (pos.X == -1 || pos.Y == -1 || result.ContainsKey(pos.X))
						{
							continue;
						}

						result[pos.X] = new Dictionary()
						{
							{ "color", new Color(0.0f, 0.0f, 1.0f) }
						};
					}

					foreach (int pos in result.Keys.ToList())
					{
						var patternEndIndex = pos + patternText.Length;
						if (result.ContainsKey(patternEndIndex))
						{
							continue;
						}

						result[patternEndIndex] = new Dictionary()
						{
							{ "color", new Color(1.0f, 1.0f, 1.0f) }
						};
					}

					if (!result.ContainsKey(0))
					{
						result[0] = new Dictionary()
						{
							{ "color", new Color(1.0f, 1.0f, 1.0f) }
						};
					}

					var needSortKeys = result.Keys.ToList();

					needSortKeys.Sort((x1, x2) =&gt; ((int)x1).CompareTo((int)x2));

					Dictionary sortResult = new Dictionary();

					foreach (var sortKey in needSortKeys)
					{
						sortResult[sortKey] = result[sortKey];
					}

					return sortResult;
				}
				[/csharp]
				[/codeblocks]
